import {createReferencePages,renderArticleBody} from './reference-pages.js';
import {createPortalPages} from './portal-pages.js';
import {REFERENCE_TAG_PAGES} from './reference-catalog.js';
import {SITE_CONTENT} from './content-data.js';

export function createExtendedUI(ctx){
 const {api,esc,money,date,go,toast,showDialog}=ctx,$=s=>document.querySelector(s),site=()=>ctx.getSite();
 let data={posts:[],feedback:[]},helpCategory='全部',faqCategory='全部',feedbackCategory='全部',shopCategory='全部',creditChoice='credits500',selectedPlan='plus',queryMode='order',receiptLanguage='zh',adminTab='orders',adminItems=[],orders=[],requests=[],lightboxIndex=0;
 const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
 const activationLabels={none:'尚未提交',requested:'待处理',processing:'激活处理中',completed:'激活已完成',rejected:'需联系客服'};
 const intents={new:'新开通',renew:'到期续费',upgrade:'升级套餐'};
 const heading=(k,title,description)=>`<div class="page-title"><span class="eyebrow">${esc(k)}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div>`;
 const paragraph=t=>String(t).split(/\n\n/).map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('');
 const link=(url,text,outline=false)=>`<a class="btn ${outline?'outline':''}" href="${esc(url)}">${esc(text)} <span>→</span></a>`;
 const product=id=>site().products.find(p=>p.id===id);
 const category=p=>['gemini','grok','claude'].includes(p.id)?p.id:p.category;
 const live=p=>p&&site().acceptingOrders&&p.enabled&&Number.isInteger(p.price_cents)&&(p.delivery_mode!=='card'||p.available_cards>0);
 const purchaseUrl=id=>({plus:'/purchase',go:'/purchase-go',plusaccount:'/purchase-gptplus',pro100:'/purchase-gptpro?tier=gptprolite',pro200:'/purchase-gptpro?tier=gptpro',credits500:'/purchase_credits',credits1000:'/purchase_credits',credits1500:'/purchase_credits'})[id]||'/checkout?plan='+id;
 function card(p,featured=false){if(!p)return '';return `<article class="plan ${featured?'featured':''}">${featured?'<span class="plan-ribbon">常用方案</span>':''}<div class="plan-symbol">${p.id.startsWith('credits')?'▤':p.id.startsWith('pro')?'↗':'✦'}</div><h3>${esc(p.name)}</h3><p class="muted">${esc(p.subtitle)}</p><div class="price">${money(p.price_cents)}${p.price_cents?`<small>/ ${esc(p.billing_label)}</small>`:''}</div>${p.original_price_cents>p.price_cents&&p.price_cents?`<div class="price-saving"><s>${money(p.original_price_cents)}</s><span>节省 ${money(p.original_price_cents-p.price_cents)}</span></div>`:''}<p class="plan-note">${p.delivery_mode==='card'?'卡密交付 · 核实到账后自动发放':'人工办理 · 条件先确认'}</p><ul>${p.features.map(x=>`<li>✓ <span>${esc(x)}</span></li>`).join('')}</ul>${p.delivery_mode==='card'?`<p class="muted">可发库存 ${p.available_cards} 张 · 每单一张</p>`:''}${live(p)?link(purchaseUrl(p.id),p.delivery_mode==='card'?'购买卡密':'选择套餐'): '<button class="btn full outline" data-action="contact">'+(p.enabled&&p.delivery_mode==='card'&&!p.available_cards?'暂时缺货 · 联系客服':'咨询办理条件')+' →</button>'}</article>`;}
 function nav(){return `<div class="announcement"><span>${esc(site().announcement||'付款由客服核实，卡密商品确认后自动发放。')}</span><a href="/gptpro">查看 Pro 方案 →</a></div><header class="header"><div class="wrap nav"><a class="brand" href="/"><span class="brand-mark">A</span><span>${esc(site().brand)}<small>AI 订阅与卡密服务</small></span></a><nav id="navlinks"><a href="/plus-price">ChatGPT 充值</a><a href="/gptpro">Pro 专区</a><a href="/codex">Codex</a><a href="/guide">充值教程</a><a href="/faq">常见问题</a><a href="/help">充值排查</a><a href="/blog">博客指南</a><details class="more-nav"><summary>更多 AI</summary><div><a href="/gemini-pro">Gemini</a><a href="/grok">Grok</a><a href="/claude">Claude</a><a href="/team">Business / 团队</a><a href="/gpt20x">Pro 提前续费</a><a href="/gpt20-upgrade">升级核价</a><a href="/xiaodian">全部商品</a><a href="/ip">网络信息</a></div></details></nav><div class="nav-end"><a class="order-link" href="/order">查询订单</a><button class="menu-btn" data-action="menu" aria-label="展开导航">☰</button></div></div></header>`;}
 function footer(){return `<footer><div class="wrap footer-grid"><div><a class="brand" href="/"><span class="brand-mark">A</span><span>${esc(site().brand)}</span></a><p>支付宝 / 微信付款，商家核实收款。<br>卡密自动交付，人工办理持续跟进。</p><p class="muted">本站为独立第三方服务，与 AI 产品厂商无官方隶属关系。</p>${site().supportQr?`<button class="text-button" data-action="contact">扫码联系客服 →</button>`:''}</div><div><b>ChatGPT 充值</b><a href="/chatgpt-plus">Plus 订阅办理</a><a href="/chatgpt-pro">Pro 升级与续费</a><a href="/plus-price">套餐与价格</a><a href="/purchase_credits">Codex 点数</a><a href="/team">企业与 Business</a><a href="/purchase-team">Business 购买</a></div><div><b>AI 与教程</b><a href="/codex">Codex 使用指南</a><a href="/gemini-pro">Gemini</a><a href="/grok">Grok</a><a href="/claude">Claude</a><a href="/guide">充值图文教程</a><a href="/blog">博客与指南</a></div><div><b>帮助与支持</b><a href="/faq">常见问题</a><a href="/help">充值排查</a><a href="/gptget">卡密激活</a><a href="/order">订单与收款凭证</a><a href="/feedback">服务反馈</a><a href="/ip">网络环境信息</a><a href="/gift">续费优惠</a><a href="/coupons">我的优惠</a><a href="/share">分享与推荐</a><a href="/invoice">收款凭证服务</a><a href="/admin">管理后台</a></div></div><div class="wrap footer-bottom"><span>© ${new Date().getFullYear()} ${esc(site().businessName||site().brand)}</span><span><a href="/about">关于我们</a><a href="/privacy">隐私政策</a><a href="/terms">服务条款</a></span></div></footer><button class="floating" data-action="contact" aria-label="联系客服">✦ <span>客服</span></button>`;}
 function workflow(step=0){return `<div class="demo-workflow" data-demo-step="${step}"><div class="visual-top"><span class="window-dots">● ● ●</span><span>流程示意 · 非真实交易</span></div><div class="visual-content"><span class="mini-tag">ORDER & DELIVERY</span><h3>${['选择套餐，保存订单','核实付款，领取卡密','按说明兑换，核对结果'][step]}</h3><div class="demo-product"><span>✦</span><div><b>${esc(site().brand)}</b><small>${['套餐与交付方式先确认','一单一张，卡密专属领取','外部兑换 / 本站人工激活'][step]}</small></div></div>${['订单创建','确认收款','卡密交付 / 人工处理'].map((t,i)=>`<div class="mock-step ${i<=step?'done':''}"><i>${i<=step?'✓':i+1}</i><div><b>${t}</b><small>${['订单号与查询凭证保密保存','提交付款信息后等待商家核实','缺货补发，办理进度可查'][i]}</small></div></div>`).join('')}<div class="visual-note">实际金额、服务时间与兑换方式以订单说明为准。</div></div></div>`;}
 function faqRows(rows){return rows.map(q=>`<details class="faq"><summary>${esc(q.question)}<span>＋</span></summary><div>${paragraph(q.answer)}${q.link?`<a class="link-arrow" href="${esc(q.link)}">查看相关说明 →</a>`:''}</div></details>`).join('');}
 function home(){return `<section class="hero hero-centered"><div class="wrap"><h1>ChatGPT Plus/Pro<br>充值服务</h1><h2 class="hero-subtitle">原账号办理 · 卡密自动交付</h2><p class="hero-description">${esc(site().brand)} 为你安排合适的 AI 订阅。支持支付宝、微信付款，<br class="desktop-break">客服核实到账后，按所选商品交付卡密或办理充值。</p><div class="hero-buttons">${link('/plus-price','立即充值')}</div><a class="hero-pro" href="/gptpro"><span>Pro</span> 查看 Pro 订阅方案 ›</a><p class="hero-proof">自己的账号 · 明确的交付说明 · 订单进度可查</p><div class="hero-benefits"><article><i>◇</i><div><b>条件先确认</b><small>商品与账号要求清楚可查</small></div></article><article><i>ϟ</i><div><b>卡密自动交付</b><small>确认收款后专属领取</small></div></article><article><i>▤</i><div><b>支付便捷</b><small>支付宝 / 微信个人收款</small></div></article></div><a class="scroll-hint" href="#recharge-flow">下滑查看充值流程 ↓</a><div class="scroll-line"></div></div></section><section class="wrap section"><div class="section-heading centered"><span class="eyebrow">核心优势</span><h2>为什么选择 ${esc(site().brand)}</h2><p>把购买、交付与售后说明清楚，每一笔订单都有记录。</p></div><div class="advantage-grid">${[['◇','原账号与独立使用','先确认实际商品及账号要求，选择适合自己的办理方式。'],['▤','无需海外付款卡','已配置的支付宝和微信方式会显示在订单中。'],['✓','专属订单凭证','卡密与收款凭证仅通过该订单的查询凭证访问。'],['✦','人工客服跟进','核实付款、缺货补发和办理问题由商家跟进。']].map(([i,h,p])=>`<article><i>${i}</i><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section class="tint" id="recharge-flow"><div class="wrap section"><div class="section-heading centered"><span class="eyebrow">充值流程</span><h2>从购买到交付，按步骤完成</h2><p>选择套餐、核实付款，再按交付说明使用。</p></div><div class="flow-grid"><div class="flow-steps">${[['选择套餐并创建订单','确认商品金额、周期与交付方式。'],['付款并领取卡密','提交付款信息，商家核实到账后自动发卡。'],['完成兑换或账号办理','按兑换说明操作，回到自己的账号核对结果。']].map(([h,p],i)=>`<button class="flow-step-button ${i===0?'active':''}" data-action="flow-step" data-index="${i}"><span>${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></button>`).join('')}</div><div id="workflow-demo">${workflow()}</div></div><div class="center">${link('/guide','查看完整图文教程',true)}</div></div></section><section class="wrap section"><div class="section-heading centered"><span class="eyebrow">服务反馈</span><h2>查看公开服务记录</h2><p>仅展示本站发布的反馈素材，点击图片可放大查看。</p></div>${data.feedback.length?`<div class="feedback-strip">${data.feedback.slice(0,6).map((f,i)=>feedbackCard(f,i)).join('')}</div>`:'<div class="feedback-empty"><span>◎</span><div><h3>目前暂无公开客户反馈</h3><p>办理前可先咨询商品条件、处理时间与售后范围。</p></div><button class="btn outline small" data-action="contact">咨询客服 ↗</button></div>'}<div class="center spaced">${link('/feedback','查看反馈图库',true)}</div></section><section class="tint"><div class="wrap narrow section"><div class="section-heading centered"><span class="eyebrow">常见问题</span><h2>充值、卡密与账号问题</h2><p>搜索问题，或按分类查找说明。</p></div>${questionSearch(false,true)}</div></section><section class="wrap section"><div class="section-heading"><div><span class="eyebrow">教程与指南</span><h2>购买前后，都有步骤可参考</h2><p>套餐选购、卡密兑换、账号与用量核对。</p></div><a class="link-arrow" href="/blog">查看全部指南 ↗</a></div><div class="article-grid">${data.posts.slice(0,4).map(articleCard).join('')}</div></section><section class="tint"><div class="wrap narrow section"><div class="section-heading centered"><h2>充值视频与图文教程</h2><p>先了解流程，再选择办理方案。</p></div>${videoPanel()}</div></section>`;}
 function pricePage(){return `<div class="wrap section">${heading('CHOOSE YOUR PLAN','选择适合你的 ChatGPT 方案','先确认账号条件、订阅周期和交付方式，再下单付款。')}<div class="quick-guides"><a href="/blog/chatgpt-register-guide">还没有账号？注册与登录说明 →</a><a href="/blog/codex-phone-verification">登录要求手机号验证？查看指南 →</a><a href="/gptget">已有卡密？前往激活 →</a></div>${!site().acceptingOrders?'<div class="notice">网站暂未开放下单，商品价格与办理条件请先咨询客服。</div>':''}<div class="plans plan-selection">${['plus','pro100','pro200'].map(id=>`<div class="selectable-plan"><label class="plan-selector"><input type="radio" name="selectedPlan" value="${id}" ${selectedPlan===id?'checked':''} data-action="plan-select" data-id="${id}"><span>选择 ${esc(product(id)?.name)}</span></label>${card(product(id),id===selectedPlan)}</div>`).join('')}</div><div class="center">${link('/gptpro','查看 Pro 档位与办理说明',true)}</div><div class="extra-product-grid">${['plusaccount','go'].map(id=>card(product(id))).join('')}<article class="panel"><span class="eyebrow">CODEX CREDITS</span><h3>Codex 点数充值</h3><p>500 / 1000 / 1500 点数商品，价格及库存由商家配置。</p>${link('/purchase_credits','查看点数方案',true)}</article><article class="panel"><span class="eyebrow">BUSINESS</span><h3>Business / 企业办理</h3><p>提交席位数量和需求，客服核对方案。</p>${link('/team','企业咨询',true)}</article></div></div>`;}
 function proPage(){const tier=new URLSearchParams(location.search).get('tier'),current=tier==='gptprolite'?'pro100':tier==='gptpro'?'pro200':selectedPlan.startsWith('pro')?selectedPlan:'pro100';return `<div class="wrap section">${heading('CHATGPT PRO','Pro 升级与到期续费','按你的实际使用需求，选择档位和办理类型。')}<details class="notice"><summary>购买前先确认当前订阅和额度</summary><p>记录账号当前套餐、到期日及用量。历史 5x / 20x 名称与当前实际权益可能不同，商品以商家说明和官方账号显示为准；升级不保证立即清零用量。</p></details><div class="tier-tabs">${['pro100','pro200'].map(id=>`<a class="${id===current?'active':''}" href="/gptpro?tier=${id==='pro100'?'gptprolite':'gptpro'}#pro-plans">${esc(product(id)?.name)}</a>`).join('')}</div><div class="plans two" id="pro-plans">${['pro100','pro200'].map(id=>card(product(id),id===current)).join('')}</div><section class="panel pro-higher"><div><h3>更高档位办理咨询</h3><p>高频开发或企业需求，先核对真实渠道和报价。</p></div>${card(product('pro500'))}</section><div class="compare-table panel"><h2>办理方式先确认</h2><table><thead><tr><th>类型</th><th>适用情况</th><th>购买前确认</th></tr></thead><tbody><tr><td>新开通</td><td>当前没有对应订阅</td><td>账号正常登录、所选档位可办理</td></tr><tr><td>到期续费</td><td>已有订阅，需要继续使用</td><td>原到期日、续费周期与剩余天数</td></tr><tr><td>升级套餐</td><td>希望切换至更高方案</td><td>升级资格、实际报价与额度变化</td></tr></tbody></table></div><div class="info-grid"><article><h3>原账号办理</h3><p>账号验证由本人完成，表单不接收密码或会话凭证。</p></article><article><h3>额度与有效期分开核对</h3><p>续费、重置时间和额外点数分别确认。</p></article><article><h3>更高档位或批量方案</h3><p>先咨询真实渠道与价格，客服确认后再付款。</p><a href="/team" class="link-arrow">提交企业需求 →</a></article></div>${faqRows(SITE_CONTENT.faq.filter(q=>['Plus 和 Pro 应该怎么选？','续费会立即重置用量吗？','可以取消或退款吗？'].includes(q.question)))}</div>`;}
 function stepper(active=0){return `<ol class="checkout-stepper">${['填写信息','扫码付款','领取 / 办理','核对结果'].map((t,i)=>`<li class="${i<=active?'active':''}"><span>${i+1}</span>${t}</li>`).join('')}</ol>`;}
 function purchase(id,defaultIntent='new'){const p=product(id);if(!p)return missing();const isCard=p.delivery_mode==='card',intent=new URLSearchParams(location.search).get('intent')||defaultIntent;return `<div class="purchase-background"><div class="wrap purchase-wrap"><a class="link-arrow" href="/plus-price">‹ 返回套餐</a>${stepper()}<section class="purchase-summary"><div class="purchase-symbol">✦</div><div><span class="eyebrow">${isCard?'CARD DELIVERY':'MANUAL SERVICE'}</span><h1>${esc(p.name)}</h1><div class="purchase-tags"><span>条件先确认</span><span>订单可查询</span><span>客服跟进</span></div><div class="price">${money(p.price_cents)}${p.price_cents?`<small>/ ${esc(p.billing_label)}</small>`:''}</div>${p.original_price_cents>p.price_cents&&p.price_cents?`<div class="price-saving"><s>${money(p.original_price_cents)}</s><span>节省 ${money(p.original_price_cents-p.price_cents)}</span></div>`:''}<p>${isCard?'客服确认到账后，系统自动分配一张卡密。':'客服确认到账后，按商品说明安排办理。'}</p></div></section><div class="purchase-columns"><section class="panel"><h2>购买前先了解</h2>${faqRows(SITE_CONTENT.faq.filter(q=>['卡密和人工充值有什么区别？','点击已付款会立即发卡吗？','需要提供密码或会话 Token 吗？','卡密在哪里领取？','可以取消或退款吗？'].includes(q.question)))}<div class="purchase-instructions"><h3>${isCard?'兑换说明':'办理说明'}</h3>${paragraph(p.delivery_instructions||'请先确认账号状态、订阅周期和预计处理时间，再安排付款。')}<p class="muted">${isCard?'每个订单一张卡密。下单不预占库存，缺货时由客服联系补货或退款。':'办理前核对你自己的账号和所选商品。'}</p></div></section><form id="checkout-form" class="panel purchase-order" data-product="${p.id}"><h2>订单详情</h2><div class="order-total"><span>${esc(p.name)}</span><b>${money(p.price_cents)}</b></div><label>办理类型<select name="serviceIntent">${Object.entries(intents).map(([k,v])=>`<option value="${k}" ${k===intent?'selected':''}>${v}</option>`).join('')}</select></label><label>联系方式<div class="phone-field"><select name="phoneRegion" aria-label="联系区号"><option value="">微信 / 邮箱</option><option value="+86">中国大陆 +86</option><option value="+852">中国香港 +852</option><option value="+853">中国澳门 +853</option><option value="+886">中国台湾 +886</option><option value="other">其他地区</option></select><input name="contact" required maxlength="120" placeholder="微信号、手机号或邮箱"></div></label><p class="muted">用于联系与订单查询，不会通过手机号自动关联 AI 账号。</p><label>${isCard?'联系邮箱（选填）':'办理账号邮箱'}<input name="accountEmail" type="email" ${isCard?'':'required'} maxlength="180" placeholder="${isCard?'可留空':'你自己的账号邮箱'}"></label><label>付款方式<select name="method" required><option value="">请选择</option>${site().alipayQr?'<option value="alipay">支付宝个人收款</option>':''}${site().wechatQr?'<option value="wechat">微信个人收款</option>':''}</select></label><label>订单备注<textarea name="note" maxlength="500" placeholder="当前订阅或办理需求。不要填写密码、验证码或会话 Token。"></textarea></label><label class="check"><input name="agreed" type="checkbox" required><span>已阅读<a href="/privacy">隐私政策</a>和<a href="/terms">服务说明</a>，知悉付款需人工核实，交付按商品说明执行。</span></label><button class="btn full" ${live(p)?'':'disabled'}>立即购买 · ${money(p.price_cents)}</button>${!live(p)?'<p class="notice">此商品未开售或卡密缺货，请先咨询客服。</p>':''}<a class="text-button spaced" href="/guide">查看购买与办理教程 →</a></form></div></div></div>`;}
 function credits(){return `<div class="wrap section">${heading('CODEX CREDITS','Codex 点数充值','选择明确面额的商品，按订单说明领取和兑换。')}<div class="notice">套餐额度与额外点数分别核对。确认适用账号、兑换入口及余额后再购买。</div><div class="credit-options">${['credits500','credits1000','credits1500'].map(id=>`<button data-action="credit-select" data-id="${id}" class="credit-option ${creditChoice===id?'active':''}"><b>${esc(product(id)?.name)}</b><span>${money(product(id)?.price_cents)}</span><small>可发库存 ${product(id)?.available_cards||0} 张</small></button>`).join('')}</div><button class="btn outline small" data-action="refresh-catalog">刷新价格与库存 ↻</button></div>${purchase(creditChoice)}`;}
 function orderPage(){return `<div class="wrap narrow section">${heading('ORDER SERVICE','订单与服务进度','查询交付状态、领取卡密、下载收款凭证，并继续下一步办理。')}<section class="panel"><div class="query-tabs"><button data-action="query-mode" data-mode="order" class="${queryMode==='order'?'active':''}">订单号</button><button data-action="query-mode" data-mode="contact" class="${queryMode==='contact'?'active':''}">联系方式</button><button data-action="query-mode" data-mode="recovery" class="${queryMode==='recovery'?'active':''}">凭证找回</button></div>${queryMode==='recovery'?supportForm('recovery'):queryMode==='contact'?'<form id="contact-query-form"><label>下单时的联系方式<input name="contact" required maxlength="120" placeholder="原手机号、微信号或邮箱"></label><label>订单查询凭证<input name="token" type="password" required autocomplete="off"></label><button class="btn full">查询订单 →</button><p class="muted">仍需查询凭证验证，仅知道联系方式不能查看卡密。</p></form>':'<form id="query-form"><label>订单号<input name="id" required autocomplete="off" placeholder="下单后保存的订单号"></label><label>查询凭证<input name="token" type="password" required autocomplete="off" placeholder="该订单的专属查询凭证"></label><button class="btn full">查询订单 →</button></form>'}</section>${ctx.saved().length?`<section class="saved-orders"><h3>本机保存的订单</h3><p class="muted">清理浏览器数据后，需使用此前保存的查询凭证。</p>${ctx.saved().map(r=>`<button class="saved-order" data-action="open-order" data-id="${esc(r.id)}">${esc(r.id)} <span>查看进度 →</span></button>`).join('')}</section>`:''}<div id="order-result"></div><div class="info-grid"><article><h3>查找订单</h3><p>订单号或原联系方式配合凭证查询。</p></article><article><h3>核对交付方式</h3><p>区分卡密交付、外部兑换和人工办理。</p></article><article><h3>按状态继续</h3><p>付款核实、补货和激活分别显示。</p></article></div></div>`;}
 function orderExtras(o){const confirmed=['paid','processing','completed','refunded'].includes(o.status);return `<div class="order-extras">${stepper(o.status==='completed'?3:confirmed?2:o.status==='awaiting_payment'?1:1)}<p class="muted">办理类型：${esc(intents[o.serviceIntent]||'新开通')} · 商品周期：${esc(o.billingLabel||'按商品说明')}</p>${o.delivery?.mode==='card'&&o.activation?.mode==='manual'&&o.status==='completed'?`<div class="notice"><b>本站人工激活：${esc(activationLabels[o.activation.status]||'尚未提交')}</b><p>卡密交付后，按下面的入口提交账号邮箱，客服处理激活申请。</p>${o.activation.status==='none'||o.activation.status==='rejected'?link('/gptget?order='+o.id,'提交激活申请',true):''}</div>`:''}${o.productId==='business'?link('/business-recharge?order_id='+o.id,'Business 邀请与邮箱确认',true):''}${confirmed?`<div class="receipt-actions"><label>收款凭证语言<select id="receipt-language"><option value="zh">中文</option><option value="en">English</option></select></label><button class="btn outline small" data-action="download-receipt">下载 PDF 收款凭证</button></div><p class="muted">收款记录不包含卡密，不是税务发票。</p>`:''}</div>`;}
 function activation(){const id=new URLSearchParams(location.search).get('order')||'',saved=ctx.saved().find(r=>r.id===id);return `<div class="wrap narrow section">${heading('CARD ACTIVATION','卡密兑换与账号激活','先确认商品说明，再选择正确的兑换方式。')}<div class="info-grid two"><article><h3>外部兑换卡密</h3><p>到订单中指定的兑换入口使用，不需要把账号资料提交给本站。</p>${link('/order','查看兑换说明',true)}</article><article><h3>本站人工激活</h3><p>仅适用于商家开启此服务的商品。提交后由客服处理，不是上游自动充值。</p></article></div><form id="activation-form" class="panel"><h2>提交本站激活申请</h2><label>订单号<input name="orderId" required value="${esc(id)}" autocomplete="off"></label><label>查询凭证<input name="token" type="password" required value="${esc(saved?.token||'')}" autocomplete="off"></label><label>本订单发放的卡密<input name="code" required maxlength="500" autocomplete="off"></label><label>要办理的账号邮箱<input name="accountEmail" type="email" required maxlength="180"></label><label class="check"><input name="agreed" type="checkbox" required><span>已核对账号和商品说明，知道激活由客服处理。</span></label><p class="notice">不要提交账号密码、验证码、API Key 或会话 Token。未启用本站激活的商品，请使用其外部兑换入口。</p><button class="btn full">提交激活申请</button></form><div id="activation-result"></div></div>`;}
 function videoPanel(){return `<details class="tutorial-video"><summary>展开视频教程 <span>▶</span></summary>${site().tutorialVideo?`<video controls playsinline preload="none" src="${esc(site().tutorialVideo)}">浏览器无法播放时，请参考下方图文教程。</video>`:'<div class="video-empty"><span>▶</span><h3>视频正在准备中</h3><p>先查看下方图文流程，商家可在后台添加自己的教程视频。</p></div>'}</details>`;}
 function guide(){return `<div class="wrap narrow section">${heading('RECHARGE GUIDE','购买、卡密与充值教程','按步骤完成下单、付款核实、交付及验收。')}<div class="guide-navigation"><a href="#guide-step-1">1 购买商品</a><a href="#guide-step-2">2 领取与兑换</a><a href="#guide-step-3">3 核对结果</a><a href="/guide1">详细教程</a><a href="/guide2">快捷教程</a></div><p class="center"><a class="link-arrow" href="#guide-step-2">已有卡密？直接查看第 2 步 ↓</a></p>${videoPanel()}${[['购买商品并核实付款','确认套餐、金额、周期和交付方式。保存订单号与查询凭证，扫码付款后提交付款信息，等待商家核实。','/plus-price','选择套餐'],['领取卡密或跟进人工办理','确认收款后卡密自动发放。外部兑换按商品说明操作；启用本站人工激活的卡密可以提交账号邮箱，由客服处理。','/gptget','前往激活入口'],['核对账号状态与保存凭证','区分卡密已交付和订阅已生效。回到对应账号核对套餐或余额，订单中可下载收款凭证。遇到问题请带订单号联系。','/order','查询订单']].map(([title,text,url,label],i)=>`<details class="guide-detail" id="guide-step-${i+1}" ${i===0?'open':''}><summary><span>0${i+1}</span><h2>${title}</h2><b>＋</b></summary><div class="guide-detail-body">${paragraph(text)}<div class="guide-illustration" id="guide-diagram-${i}">${workflow(i)}</div><button class="text-button spaced" data-action="zoom-diagram" data-index="${i}">放大查看流程示意 ↗</button><div class="spaced">${link(url,label,true)}</div></div></details>`).join('')}<section class="panel"><h2>注册、验证与常见问题</h2><p><a href="/blog/chatgpt-register-guide">账号注册与登录说明 →</a></p><p><a href="/blog/codex-phone-verification">手机号验证问题说明 →</a></p><p><a href="/help">充值失败与账号排查 →</a></p><button class="btn outline small" data-action="contact">展开客服信息</button></section></div>`;}
 function questionSearch(help=false,compact=false){const rows=help?SITE_CONTENT.help:SITE_CONTENT.faq,selected=help?helpCategory:faqCategory,cats=['全部',...new Set(rows.map(q=>q.category))];return `<input id="extended-question-search" class="search" data-help="${help?'yes':'no'}" placeholder="搜索问题，例如：付款、卡密、账号、额度…" aria-label="搜索问题"><div class="question-tabs">${cats.map(c=>`<button data-action="question-category" data-help="${help?'yes':'no'}" data-category="${c}" class="${c===selected?'active':''}">${c}</button>`).join('')}</div><p class="muted" id="question-count">${rows.filter(q=>selected==='全部'||q.category===selected).length} 条说明</p><div id="extended-question-results" data-help="${help?'yes':'no'}" data-compact="${compact?'yes':'no'}">${faqRows(rows.filter(q=>selected==='全部'||q.category===selected).slice(0,compact?6:undefined))}</div><div class="center spaced"><a class="link-arrow" href="${help?'/faq':'/help'}">${help?'查看售前与购买问题':'查看充值失败排查'} →</a></div>${!help&&!compact?receiptDemo():''}`;}
 function questions(help){return `<div class="wrap narrow section">${heading(help?'HELP CENTER':'FAQ',help?'充值失败与账号排查':'常见问题解答',help?'按充值、账号、使用限制和网络环境查找处理步骤。':'按分类搜索，找到购买、卡密、查询与售后说明。')}${questionSearch(help)}<section class="panel"><h2>需要客服核查？</h2><p>说明订单号、实际错误和发生时间，截图请遮盖卡密与查询凭证。</p><button class="btn outline" data-action="contact">联系客服</button></section></div>`;}
 function receiptDemo(){return `<section class="panel receipt-demo-panel"><h2>收款凭证示意</h2><div class="tier-tabs"><button data-action="receipt-demo-language" data-language="zh" class="${receiptLanguage==='zh'?'active':''}">中文</button><button data-action="receipt-demo-language" data-language="en" class="${receiptLanguage==='en'?'active':''}">English</button></div><button class="receipt-demo-button" data-action="receipt-demo-zoom"><div class="receipt-demo" id="receipt-demo"><span>${esc(site().brand)}</span><h3>${receiptLanguage==='en'?'PAYMENT RECEIPT':'收款凭证'}</h3><p>${receiptLanguage==='en'?'Sample only - no real transaction':'仅为格式示意，无真实交易'}</p><hr><p>Order / 订单：DEMO-ONLY</p><p>Amount / 金额：CNY 0.00</p><small>${receiptLanguage==='en'?'Payment record, not a tax invoice.':'收款记录，不是税务发票。'}</small></div></button><p class="muted">点击放大。实际订单确认收款后，可下载对应语言 PDF。</p></section>`;}
 function articleCard(a){return `<a class="article-card" href="/blog/${esc(a.id)}"><div class="article-art art-${a.category==='风控'?'security':a.category==='充值'?'payment':'choose'}"><span>${a.category==='Codex'?'⌘':a.category==='风控'?'◇':'✦'}</span><small>${esc(a.category)}</small></div><div class="article-meta">${esc(a.date)} · ${a.readMinutes||4} 分钟阅读</div><h3>${esc(a.title)}</h3><p>${esc(a.excerpt)}</p><div class="tag-list">${a.tags.slice(0,3).map(t=>`<span>#${esc(t)}</span>`).join('')}</div><span class="link-arrow">阅读全文 ↗</span></a>`;}
 function blog(tag=''){const decoded=decodeURIComponent(tag||''),q=new URLSearchParams(location.search).get('q')||'',mapped=REFERENCE_TAG_PAGES[decoded],ordered=mapped?mapped.articles.map(id=>data.posts.find(p=>p.id===id)).filter(Boolean).concat(data.posts.filter(p=>!mapped.articles.includes(p.id)&&p.tags.includes(decoded))):data.posts,all=ordered.filter(a=>(!decoded||mapped||a.category===decoded||a.tags.includes(decoded))&&(!q||(a.title+a.excerpt+a.tags.join(' ')).toLowerCase().includes(q.toLowerCase()))),pages=Math.max(1,Math.ceil(all.length/9)),page=Math.min(pages,Math.max(1,parseInt(new URLSearchParams(location.search).get('page'))||1)),base=decoded?'/blog/tag/'+encodeURIComponent(decoded):'/blog';return `<div class="wrap section">${heading('GUIDES & BLOG',decoded?decoded+'相关文章':'教程、套餐与使用指南','按主题查找购买、兑换、账号和网络排查说明。')}<div class="blog-tools"><div class="question-tabs"><a class="${!decoded?'active':''}" href="/blog">全部</a>${SITE_CONTENT.blogCategories.map(c=>`<a class="${decoded===c?'active':''}" href="/blog/tag/${encodeURIComponent(c)}">${c}</a>`).join('')}</div><a class="link-arrow" href="/blog/rss.xml" target="_blank">RSS 订阅 ↗</a></div><form id="blog-search-form" class="blog-search"><input name="q" value="${esc(q)}" placeholder="搜索文章、标签或问题" aria-label="搜索文章"><button class="btn outline small">搜索</button></form><p class="muted">${all.length} 篇指南 · 第 ${page} / ${pages} 页</p><div class="article-grid">${all.slice((page-1)*9,page*9).map(articleCard).join('')||'<p class="muted">没有匹配的文章，试试其他关键词。</p>'}</div><nav class="pagination" aria-label="博客分页">${Array.from({length:pages},(_,i)=>`<a href="${base}?page=${i+1}${q?'&q='+encodeURIComponent(q):''}" class="${page===i+1?'active':''}">${i+1}</a>`).join('')}</nav><div class="tag-cloud">${[...new Set(data.posts.flatMap(a=>a.tags))].map(t=>`<a href="/blog/tag/${encodeURIComponent(t)}">#${esc(t)}</a>`).join('')}</div></div>`;}
 function article(id){const aliases={choose:'chatgpt-plus-vs-pro-comparison-2026',payment:'chatgpt-plus-how-to-buy-2026',verify:'chatgpt-plus-upgrade-guide',security:'chatgpt-register-guide'},a=data.posts.find(a=>a.id===(aliases[id]||id));if(!a)return missing();return `<div class="wrap section article-layout"><aside class="article-toc"><span class="eyebrow">本页目录</span>${a.sections.map((s,i)=>`<a href="#article-section-${i}">${esc(s.heading)}</a>`).join('')}<a class="link-arrow" href="/blog">← 返回指南</a></aside><article class="prose"><a class="eyebrow" href="/blog/tag/${encodeURIComponent(a.category)}">${esc(a.category)}</a><h1>${esc(a.title)}</h1><p class="article-meta">${esc(a.date)} · ${a.readMinutes||4} 分钟阅读 · ${esc(a.author||site().brand)}</p><div class="tag-list">${a.tags.map(t=>`<a href="/blog/tag/${encodeURIComponent(t)}">#${esc(t)}</a>`).join('')}</div><p class="article-intro">${esc(a.excerpt)}</p>${a.sections.map((s,i)=>`<section id="article-section-${i}"><h2>${esc(s.heading)}</h2>${renderArticleBody(s.text,esc)}</section>`).join('')}<div class="article-cta"><h3>确认方案，再开始办理</h3>${link('/plus-price','查看套餐')} ${link('/help','问题排查',true)}</div><h2>相关指南</h2><div class="related-posts">${data.posts.filter(p=>p.id!==a.id&&p.category===a.category).slice(0,3).map(p=>`<a href="/blog/${p.id}">${esc(p.title)} →</a>`).join('')}</div></article></div>`;}
 function feedbackCard(f,index){return `<button class="feedback-card" data-action="feedback-zoom" data-index="${index}"><img loading="lazy" src="${esc(f.image)}" alt="${esc(f.title)}"><span>${esc(f.category)}</span><b>${esc(f.title)}</b><small>${esc(f.date||'')}</small></button>`;}
 function feedback(){const visible=data.feedback.map((f,i)=>({...f,index:i})).filter(f=>feedbackCategory==='全部'||f.category===feedbackCategory);return `<div class="wrap section">${heading('SERVICE FEEDBACK','服务反馈图库','仅展示本站发布的真实服务记录，点击图片可放大查看。')}<div class="question-tabs">${['全部','到账反馈','客服答疑','使用体验','售后处理'].map(c=>`<button data-action="feedback-category" data-category="${c}" class="${c===feedbackCategory?'active':''}">${c}</button>`).join('')}</div><p class="muted">${visible.length} 条公开反馈</p><div class="feedback-gallery">${visible.map(f=>feedbackCard(f,f.index)).join('')||'<div class="feedback-empty"><h3>目前暂无该分类的公开反馈</h3><p>办理前可先联系客服确认商品条件和售后范围。</p></div>'}</div></div>`;}
 function showFeedback(){const f=data.feedback[lightboxIndex];if(!f)return;showDialog(`<div class="feedback-lightbox"><h2>${esc(f.title)}</h2><img src="${esc(f.image)}" alt="${esc(f.title)}"><p>${esc(f.caption||'')}</p><div class="lightbox-controls"><button class="btn outline small" data-action="feedback-prev">上一张</button><span>${lightboxIndex+1} / ${data.feedback.length}</span><button class="btn outline small" data-action="feedback-next">下一张</button></div></div>`);}
 function codex(){return `<div class="wrap section">${heading('CODEX & CREDITS','Codex 订阅与用量指南','先确认账号、任务入口和实际用量，再选择订阅或点数商品。')}<div class="codex-intro"><div><h2>按自己的工作方式使用</h2><p>桌面端、命令行、IDE 和网页入口各有适用场景。核对同一个账号和自己的项目资料，订阅办理与客户端安装分开处理。</p>${link('/purchase_credits','查看点数商品')} ${link('/plus-price','比较订阅',true)}</div><div class="codex-terminal"><span>YOUR WORKSPACE</span><pre>任务与项目\n  → 确认登录账号\n  → 查看实际用量\n  → 选择订阅或点数\n  → 验证余额与结果</pre><small>流程说明，不是额度承诺</small></div></div><div class="advantage-grid">${[['桌面端','在可视界面查看任务与项目安排。'],['命令行','适合习惯终端操作的工作方式。'],['IDE','围绕当前代码与开发环境使用。'],['网页任务','按产品实际开放的入口处理任务。']].map(([h,p])=>`<article><i>⌘</i><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><section class="panel spaced"><h2>订阅、点数和重置分开看</h2><div class="table-scroll"><table><thead><tr><th>项目</th><th>确认内容</th><th>本站入口</th></tr></thead><tbody><tr><td>订阅套餐</td><td>周期、适用账号和实际权益</td><td><a href="/plus-price">Plus / Pro →</a></td></tr><tr><td>额外 Credits</td><td>面额、兑换说明、余额页面</td><td><a href="/purchase_credits">点数商品 →</a></td></tr><tr><td>用量重置</td><td>账号面板中的重置提示</td><td><a href="/blog/codex-reset-rules-guide">重置说明 →</a></td></tr></tbody></table></div></section><div class="info-grid"><article><h3>Skills 与工作流程</h3><p>查看客户端支持的流程能力。本站不提供已经配置好的个人工作区。</p></article><article><h3>多任务与项目</h3><p>区分本机文件、账号内任务与历史记录，切换前保留需要的资料。</p></article><article><h3>官方入口</h3><p><a href="https://openai.com/codex/" target="_blank" rel="noopener noreferrer">查看官方 Codex 页面 ↗</a></p></article></div>${faqRows(SITE_CONTENT.faq.filter(q=>q.category==='Codex'))}</div>`;}
 function aiService(kind){const groups={gemini:['gemini','geminiaccount','geminiyear'],grok:['grok','grokquarter'],claude:['claude']},names={gemini:'Gemini',grok:'Grok / SuperGrok',claude:'Claude'};return `<div class="wrap section">${heading('AI SUBSCRIPTIONS',names[kind]+' 订阅服务','原账号办理与独立商品分别确认，周期和交付方式以商品说明为准。')}<div class="plans ${groups[kind].length===2?'two':''}">${groups[kind].map((id,i)=>card(product(id),i===0)).join('')}</div><div class="info-grid"><article><h3>核对方案与周期</h3><p>先确认月度、季度或年度方案的实际办理范围。</p></article><article><h3>选择交付方式</h3><p>卡密按指定入口兑换，人工办理由客服确认条件后安排。</p></article><article><h3>批量需求</h3><p>提交数量与用途，客服按真实渠道确认报价。</p><a href="/team">企业与批量咨询 →</a></article></div><div class="center">${link('/xiaodian','查看全部 AI 商品',true)}</div>${faqRows(SITE_CONTENT.faq.slice(0,4))}</div>`;}
 function shop(){const list=site().products.filter(p=>shopCategory==='全部'||category(p)===shopCategory);return `<div class="wrap section">${heading('AI SHOP','AI 订阅与卡密小店','在本站选择商品、创建订单并查询交付结果。')}<div class="question-tabs">${[['全部','全部'],['chatgpt','ChatGPT'],['codex','Codex 点数'],['gemini','Gemini'],['grok','Grok'],['claude','Claude'],['other','其他']].map(([c,t])=>`<button data-action="shop-category" data-category="${c}" class="${c===shopCategory?'active':''}">${t}</button>`).join('')}</div><div class="shop-plans">${list.map(p=>card(p)).join('')||'<p class="muted">该分类暂无商品。</p>'}</div>${site().externalShop?`<section class="panel"><h3>商家备用小店</h3><p>离开本站前，请核对目标商家和商品说明。</p><a class="btn outline" href="${esc(site().externalShop)}" target="_blank" rel="noopener noreferrer">打开商家配置的小店 ↗</a></section>`:''}</div>`;}
 function supportForm(kind){return `<form class="support-form" data-kind="${kind}"><label>${kind==='business'?'公司 / 团队与需求':'订单线索或问题说明'}<textarea name="message" required maxlength="1200" placeholder="${kind==='business'?'产品、席位数量、周期与办理要求':'订单号、商品、付款时间或遇到的问题。不要填写卡密、密码或验证码。'}"></textarea></label><label>联系方式<input name="contact" required maxlength="120"></label>${kind!=='business'?'<label>订单号（如有）<input name="orderId" maxlength="60"></label>':''}<button class="btn full">${kind==='recovery'?'提交凭证找回申请':'提交咨询申请'}</button><p class="muted">客服核实后处理，不会仅凭联系方式公开卡密。</p></form>`;}
 function team(){return `<div class="wrap section">${heading('BUSINESS & TEAM','企业批量与 Business 办理','先确认席位、账号和周期，客服按实际渠道核对方案。')}<div class="table-scroll panel"><table><thead><tr><th>方案</th><th>办理方向</th><th>购买前确认</th></tr></thead><tbody><tr><td>个人订阅</td><td>独立账号，按套餐办理</td><td>账号状态、周期、交付方式</td></tr><tr><td>团队 / Business</td><td>席位、工作区或批量需求</td><td>邀请流程、人数、权限和售后</td></tr></tbody></table></div><div class="split"><section><h2>说明需求，再安排办理</h2><p>企业渠道、价格、收款、凭证和服务范围需在办理前与客服确认。</p><ol class="team-steps"><li>提交产品、数量与预计周期</li><li>客服核对渠道和报价</li><li>确认方案后付款和办理</li></ol><button class="btn outline" data-action="contact">联系客服</button></section><section class="panel"><h2>提交企业咨询</h2>${supportForm('business')}</section></div></div>`;}
 function network(){return `<div class="wrap narrow section">${heading('NETWORK INFORMATION','IP 与网络环境信息','查询公开地区及运营商资料，不用于判断账号性能或模型质量。')}<form id="network-form" class="panel"><label>IPv4 / IPv6 地址<input name="ip" required maxlength="60" placeholder="例如 8.8.8.8" autocomplete="off"></label><button type="button" class="text-button" data-action="my-ip">填入当前请求 IP</button><label class="check"><input name="consent" type="checkbox" required><span>同意将所查询 IP 提交给 <a href="https://ipwhois.io/documentation" target="_blank" rel="noopener noreferrer">ipwho.is</a>，用于查询公开网络信息。</span></label><button class="btn full">查询网络信息</button></form><div id="network-result"></div><div class="notice">地理信息可能不准确。网络出口标签不是账号“质量分”，也不能保证模型效果。</div><a class="link-arrow" href="/blog/gpt-ip-quality-detection">查看网络排查指南 →</a></div>`;}
 function information(kind){const content={about:[['我们的服务','提供 AI 订阅办理、卡密交付与订单跟进。商品是否开售、实际价格和服务时间由商家维护。'],['交付流程','付款由客服核实，卡密自动分配；人工充值和激活申请由客服处理。'],['运营与联系',site().businessName||'运营信息与售后范围请通过本站客服确认。']],privacy:[['订单与联系资料','订单收集你填写的联系方式、必要的账号邮箱、商品和付款线索，用于办理及售后。本站不收集账号密码、验证码或会话 Token。'],['卡密与查询凭证','卡密加密保存，查询凭证在服务端保存摘要。本机保存的订单凭证用于方便查询，清理浏览器数据会移除本机记录。'],['反馈与媒体','公开展示商家发布的反馈素材和教程。发布前应处理客户隐私；未经授权的客户记录不作为本站评价。'],['网络查询','只有你确认后，输入的 IP 才会提交给 ipwho.is 查询公开地区与运营商信息。本站不将该工具结果当作账号性能诊断。'],['更正与售后','通过原购买渠道联系客服提出资料更正或订单问题，商家核实身份后处理。']],terms:[['商品与交付','购买前确认商品名称、周期、金额、交付方式与兑换说明。卡密商品一单一张，人工办理以客服实际确认的条件为准。'],['付款核实','提交付款信息不代表已经确认到账。保存付款记录和订单凭证，不要重复转账。'],['卡密与激活','卡密已发放不等于订阅已经生效。外部卡密按说明兑换；本站人工激活申请由客服处理，不承诺上游自动充值。'],['缺货与退款','下单不预占卡密，缺货订单等待补货或与客服确认退款。已发卡密不回库，退款状态不会自动撤销卡密或执行转账。'],['售后说明',site().refundPolicy],['收款凭证','可下载的收款凭证属于商家收款记录，不是税务发票。具体企业办理与凭证要求需提前确认。']]};return `<div class="wrap narrow section prose">${heading('SERVICE INFORMATION',{about:'关于我们',privacy:'隐私政策',terms:'服务条款'}[kind],'了解本站实际办理方式与服务范围。')}<nav class="policy-toc">${content[kind].map(([h],i)=>`<a href="#policy-${i}">${h}</a>`).join('')}</nav>${content[kind].map(([h,t],i)=>`<section id="policy-${i}"><h2>${h}</h2>${paragraph(t)}</section>`).join('')}<button class="btn outline" data-action="contact">联系客服</button></div>`;}
 function plusTopic(){return `<div class="wrap section">${heading('CHATGPT PLUS','ChatGPT Plus 订阅办理','先确认自己的账号，再选择人工办理或卡密交付。')}<div class="split"><div><h2>围绕自己的使用需求选购</h2><p>按实际功能、用量与预算选择订阅。本站商品交付方式、价格和周期清楚可查。</p>${link('/purchase','查看 Plus 商品')}</div>${card(product('plus'),true)}</div><div class="compare-table panel"><h2>购买方式比较</h2><table><thead><tr><th>方式</th><th>需要确认</th><th>交付</th></tr></thead><tbody><tr><td>人工办理</td><td>账号和渠道条件</td><td>客服处理并更新状态</td></tr><tr><td>卡密商品</td><td>兑换入口与适用范围</td><td>确认收款后自动发卡</td></tr><tr><td>独享账号商品</td><td>来源、控制权和找回方式</td><td>以实际商品说明为准</td></tr></tbody></table></div>${faqRows(SITE_CONTENT.faq.slice(0,6))}</div>`;}
 function missing(){return `<div class="wrap narrow section">${heading('404','没有找到这个页面','返回商品或指南继续查看。')}${link('/','返回首页')}</div>`;}

 function productForm(p){return `<form class="product-form" data-id="${p.id}"><h3>${esc(p.name)}</h3><div class="form-columns"><label>商品名称<input name="name" required maxlength="100" value="${esc(p.name)}"></label><label>分类<select name="category">${['chatgpt','codex','gemini','grok','claude','other'].map(c=>`<option value="${c}" ${category(p)===c?'selected':''}>${c}</option>`).join('')}</select></label><label>售价 / 元<input name="price" type="number" min="1" max="100000" step="0.01" value="${p.price_cents?p.price_cents/100:''}"></label><label>原价 / 元（选填）<input name="originalPrice" type="number" min="1" max="100000" step="0.01" value="${p.original_price_cents?p.original_price_cents/100:''}"></label><label>周期单位<input name="billingLabel" required maxlength="32" value="${esc(p.billing_label||'月')}" placeholder="月 / 年 / 张 / 席位"></label><label>交付方式<select name="deliveryMode"><option value="manual" ${p.delivery_mode==='manual'?'selected':''}>人工办理</option><option value="card" ${p.delivery_mode==='card'?'selected':''}>卡密自动发货</option></select></label></div><label>商品简介<input name="subtitle" maxlength="180" value="${esc(p.subtitle)}"></label><label>商品特性（每行一项，最多 8 项）<textarea name="features" rows="3">${esc(p.features.join('\n'))}</textarea></label><label>卡密激活方式<select name="activationMode"><option value="external" ${p.activation_mode==='external'?'selected':''}>按商品说明外部兑换</option><option value="manual" ${p.activation_mode==='manual'?'selected':''}>提交本站人工激活申请</option></select></label><label>办理 / 兑换说明<textarea name="deliveryInstructions" maxlength="1500" rows="3">${esc(p.delivery_instructions)}</textarea></label><div><label class="check"><input name="enabled" type="checkbox" ${p.enabled?'checked':''}><span>开售（需先配置价格和说明）</span></label><button class="btn outline small">保存商品</button></div></form>`;}
 function settingsPanel(){return `<form id="settings-form" class="panel"><h2>经营、收款与媒体设置</h2><div class="form-columns"><label>网站名称<input name="brand" value="${esc(site().brand)}" required maxlength="40"></label><label>运营名称（选填）<input name="businessName" value="${esc(site().businessName||'')}" maxlength="150"></label><label>客服微信<input name="wechat" value="${esc(site().wechat)}" maxlength="100"></label><label>客服邮箱<input name="supportEmail" type="email" value="${esc(site().supportEmail)}" maxlength="180"></label></div><label>顶部公告<input name="announcement" value="${esc(site().announcement||'')}" maxlength="300" placeholder="填写实际业务公告，留空使用默认说明"></label><label>服务时间与处理说明<input name="serviceHours" value="${esc(site().serviceHours)}" required maxlength="160"></label><label>支付宝收款二维码地址<input name="alipayQr" value="${esc(site().alipayQr)}" placeholder="/alipay.jpg 或 HTTPS 图片地址"></label><label>微信收款二维码地址<input name="wechatQr" value="${esc(site().wechatQr)}"></label><label>客服二维码图片地址<input name="supportQr" value="${esc(site().supportQr||'')}"></label><label>自己的教程视频地址<input name="tutorialVideo" value="${esc(site().tutorialVideo||'')}" placeholder="本站路径或 HTTPS 视频地址"></label><label>备用商品小店地址（选填）<input name="externalShop" value="${esc(site().externalShop||'')}" placeholder="留空使用本站商品小店"></label><label>退款和售后说明<textarea name="refundPolicy" maxlength="1200" required>${esc(site().refundPolicy)}</textarea></label><label class="check"><input name="acceptingOrders" type="checkbox" ${site().acceptingOrders?'checked':''}><span>开放客户下单</span></label><button class="btn">保存经营设置</button></form>`;}
 function contentPanel(){return `<div class="admin-grid"><section class="panel"><h2>博客文章</h2><label>选择文章编辑<select id="edit-post-select"><option value="">新建文章</option>${adminItems.filter(i=>i.kind==='blog').map(i=>`<option value="${esc(i.id)}">${esc(i.value.title)} ${i.enabled?'':'（未发布）'}</option>`).join('')}</select></label><form id="post-editor-form"><label>文章路径<input name="slug" required pattern="[a-z0-9][a-z0-9-]*" placeholder="例如 payment-guide"></label><label>标题<input name="title" required maxlength="140"></label><label>分类<select name="category">${SITE_CONTENT.blogCategories.map(c=>`<option>${c}</option>`).join('')}</select></label><label>摘要<textarea name="excerpt" required maxlength="500"></textarea></label><label>标签（逗号分隔）<input name="tags" maxlength="500"></label><label>正文<textarea name="bodyText" required rows="12" placeholder="## 章节标题&#10;正文说明&#10;&#10;## 第二个章节&#10;操作步骤"></textarea></label><div class="form-columns"><label>日期<input name="date" type="date" value="${today()}" required></label><label>预计阅读分钟<input name="readMinutes" type="number" min="1" max="60" value="4"></label></div><label class="check"><input name="enabled" type="checkbox" checked><span>发布到博客</span></label><button class="btn full">保存文章</button></form></section><section class="panel"><h2>反馈图片与图库</h2><p>发布自己的服务记录，先处理客户隐私。参考站的客户反馈不会自动进入本站。</p><form id="feedback-editor-form"><input name="id" type="hidden"><label>标题<input name="title" required maxlength="100"></label><label>分类<select name="category">${['到账反馈','客服答疑','使用体验','售后处理'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>图片地址<input name="image" required maxlength="1000" placeholder="本站路径或 HTTPS 图片地址"></label><label>日期<input name="date" type="date"></label><label>图片说明<textarea name="caption" maxlength="300"></textarea></label><label class="check"><input name="enabled" type="checkbox"><span>发布到公开反馈图库</span></label><button class="btn full">保存反馈</button></form><div class="admin-content-list">${adminItems.filter(i=>i.kind==='feedback').map(i=>`<article><b>${esc(i.value.title)}</b><small>${i.enabled?'已发布':'未发布'} · ${esc(i.value.category)}</small><button class="btn outline small" data-action="content-toggle" data-id="${esc(i.id)}" data-enabled="${i.enabled?'no':'yes'}">${i.enabled?'撤下':'发布'}</button></article>`).join('')||'<p class="muted">暂无反馈素材。</p>'}</div></section></div>`;}
 async function adminPage(){const session=await api('/api/admin/session');if(!session.authenticated){if(ctx.authKind==='standalone')return `<div class="wrap narrow section">${heading('MANAGEMENT','管理后台','登录后管理订单、商品、卡密和内容。')}<form id="login-form" class="panel"><label>管理密码<input type="password" name="password" required autocomplete="current-password"></label><button class="btn full" ${session.configured?'':'disabled'}>登录后台</button></form></div>`;return `<div class="wrap narrow section">${heading('MANAGEMENT','管理后台','使用已绑定的 ChatGPT 账号管理网站。')}<div class="panel">${session.canClaim?'<p>首次进入，请绑定当前所有者账号。</p><button class="btn full" data-action="claim-admin">绑定我的管理账号</button>':session.signedIn?'<p>当前账号没有本站管理权限。</p><a class="btn full" href="/signout-with-chatgpt?return_to=/admin" target="_top">切换账号</a>':'<a class="btn full" href="/signin-with-chatgpt?return_to=/admin" target="_top">使用 ChatGPT 登录 →</a>'}</div></div>`;}
  const result=await api('/api/admin/orders');orders=result.orders;ctx.setAdminOrders(orders);const stock=await api('/api/admin/cards');adminItems=(await api('/api/admin/content')).items;requests=(await api('/api/admin/requests')).requests;
  const tabs=[['orders','订单与申请'],['catalog','商品与卡密'],['content','博客与反馈'],['settings','经营设置']];let panel;
  if(adminTab==='catalog')panel=ctx.inventoryPanel(stock)+`<section class="panel"><h2>商品与套餐管理</h2><p>实际售价、周期、交付与激活说明都由你配置。</p>${site().products.map(productForm).join('')}</section><section class="panel"><h2>新增商品</h2><form id="new-product-form"><label>商品编号<input name="id" required pattern="[a-z0-9]{1,40}" maxlength="40" placeholder="小写字母与数字，保存后不更改"></label><label>商品名称<input name="name" required maxlength="100"></label><label>分类<select name="category">${['chatgpt','codex','gemini','grok','claude','other'].map(c=>`<option>${c}</option>`).join('')}</select></label><button class="btn">创建未开售商品</button></form></section>`;
  else if(adminTab==='content')panel=contentPanel();else if(adminTab==='settings')panel=settingsPanel();else panel=`<div class="stats">${[['订单总数',orders.length],['待核实',orders.filter(o=>o.status==='payment_submitted').length],['待激活',orders.filter(o=>o.activation_status==='requested').length],['新咨询',requests.filter(r=>r.status==='new').length]].map(([t,n])=>`<article class="panel"><span>${t}</span><b>${n}</b></article>`).join('')}</div><section class="panel"><div class="section-heading"><h2>最近订单</h2><a class="btn outline small" href="/api/admin/export">导出 CSV</a></div><input id="admin-order-search" class="search" placeholder="搜索订单号、联系方式或账号" aria-label="搜索订单"><div class="table-scroll"><table><thead><tr><th>订单</th><th>商品 / 金额</th><th>联系 / 账号</th><th>状态</th><th>操作</th></tr></thead><tbody id="admin-order-rows">${orders.map(o=>`<tr data-search="${esc((o.id+' '+o.contact+' '+o.account_email+' '+o.activation_email).toLowerCase())}"><td><b>${esc(o.id)}</b><small>${esc(date(o.created_at))}</small><small>${esc(intents[o.service_intent]||'新开通')}</small></td><td>${esc(o.product_name)}<small>${money(o.amount_cents)}</small></td><td>${esc(o.contact)}<small>${esc(o.account_email)}</small>${o.activation_email?`<small>激活：${esc(o.activation_email)}</small>`:''}</td><td><span class="badge">${o.delivery_mode==='card'&&o.status==='paid'?'已收款 · 待补货':esc(result.statuses[o.status])}</span>${o.activation_status!=='none'?`<small>${esc(activationLabels[o.activation_status])}</small>`:''}</td><td><button class="btn outline small" data-action="manage-order" data-id="${o.id}">处理订单</button>${o.delivery_mode==='card'&&o.status==='paid'?`<button class="btn small spaced" data-action="deliver-card" data-id="${o.id}">补发卡密</button>`:''}${['requested','processing'].includes(o.activation_status)?`<button class="btn outline small spaced" data-action="manage-activation" data-id="${o.id}">处理激活</button>`:''}<button class="text-button spaced" data-action="reissue-token" data-id="${o.id}">重发查询凭证</button></td></tr>`).join('')||'<tr><td colspan="5">暂无订单。</td></tr>'}</tbody></table></div></section><section class="panel"><h2>咨询、找回与企业申请</h2><div class="table-scroll"><table><thead><tr><th>类型 / 时间</th><th>联系 / 订单</th><th>说明</th><th>状态</th><th>操作</th></tr></thead><tbody>${requests.map(r=>`<tr><td>${esc({recovery:'凭证找回',business:'企业咨询',support:'服务咨询',business_invite:'Business 邀请',renewal:'提前续费',upgrade:'升级核价',discount:'续费优惠',referral:'推荐活动',reinvite:'重新邀请'}[r.kind])}<small>${esc(date(r.created_at))}</small></td><td>${esc(r.contact)}<small>${esc(r.order_id)}</small></td><td>${esc(r.message)}</td><td>${esc({new:'待处理',working:'处理中',resolved:'已处理'}[r.status])}</td><td><button class="btn outline small" data-action="manage-request" data-id="${r.id}">处理</button></td></tr>`).join('')||'<tr><td colspan="5">暂无申请。</td></tr>'}</tbody></table></div></section>`;
  return `<div class="wrap section admin"><div class="section-heading"><div><span class="eyebrow">MANAGEMENT</span><h1>订单与经营后台</h1><p>先核实收款，再按商品交付方式处理。</p></div>${ctx.authKind==='standalone'?'<button class="btn outline small" data-action="logout">退出登录</button>':'<a class="btn outline small" href="/signout-with-chatgpt?return_to=/admin" target="_top">退出登录</a>'}</div><nav class="admin-tabs">${tabs.map(([id,title])=>`<button data-action="admin-tab" data-tab="${id}" class="${adminTab===id?'active':''}">${title}</button>`).join('')}</nav>${panel}</div>`;
 }
 function contact(){showDialog(`<div class="contact-icon">✦</div><h2>联系订阅客服</h2><p>${esc(site().serviceHours)}</p>${site().supportQr?`<img class="support-qr" src="${esc(site().supportQr)}" alt="本站客服二维码">`:''}${site().wechat?`<div class="contact-row"><span>客服微信</span><b>${esc(site().wechat)}</b></div><button class="btn outline small" data-action="copy-support">复制微信号</button>`:''}${site().supportEmail?`<div class="contact-row"><span>客服邮箱</span><a href="mailto:${esc(site().supportEmail)}">${esc(site().supportEmail)}</a></div>`:''}${!site().wechat&&!site().supportEmail?'<div class="notice">客服信息尚未配置，请稍后再来。</div>':''}<p class="muted">说明商品和需求；售后请提供订单号，不公开卡密与查询凭证。</p>`);}
 function filterQuestions(){const input=$('#extended-question-search');if(!input)return;const help=input.dataset.help==='yes',rows=help?SITE_CONTENT.help:SITE_CONTENT.faq,chosen=help?helpCategory:faqCategory,q=input.value.trim().toLowerCase(),filtered=rows.filter(x=>(chosen==='全部'||x.category===chosen)&&(!q||(x.question+x.answer).toLowerCase().includes(q))),compact=$('#extended-question-results').dataset.compact==='yes';$('#extended-question-results').innerHTML=faqRows(compact?filtered.slice(0,6):filtered)||'<p class="muted">没有匹配说明，请换个关键词或联系客服。</p>';$('#question-count').textContent=filtered.length+' 条说明';document.querySelectorAll('[data-action="question-category"]').forEach(b=>b.classList.toggle('active',b.dataset.category===chosen));}
 async function onClick(button){const action=button.dataset.action;
  if(action==='contact'){contact();return true;}if(action==='copy-support'){await navigator.clipboard.writeText(site().wechat);toast('客服微信已复制。');return true;}
  if(action==='flow-step'){$('#workflow-demo').innerHTML=workflow(Number(button.dataset.index));document.querySelectorAll('[data-action="flow-step"]').forEach(b=>b.classList.toggle('active',b===button));return true;}
  if(action==='plan-select'){selectedPlan=button.dataset.id;go('/plus-price');return true;}if(action==='credit-select'){creditChoice=button.dataset.id;go('/purchase_credits');return true;}if(action==='refresh-catalog'){await ctx.refresh();toast('价格与库存已刷新。');return true;}
  if(action==='query-mode'){queryMode=button.dataset.mode;go('/order');return true;}if(action==='question-category'){if(button.dataset.help==='yes')helpCategory=button.dataset.category;else faqCategory=button.dataset.category;filterQuestions();return true;}
  if(action==='receipt-demo-language'){receiptLanguage=button.dataset.language;go('/faq');return true;}if(action==='receipt-demo-zoom'){showDialog('<div class="receipt-demo-dialog">'+$('#receipt-demo').outerHTML+'</div>');return true;}
  if(action==='zoom-diagram'){showDialog('<div class="diagram-dialog"><h2>流程示意</h2>'+workflow(Number(button.dataset.index))+'</div>');return true;}
  if(action==='feedback-category'){feedbackCategory=button.dataset.category;go('/feedback');return true;}if(action==='feedback-zoom'){lightboxIndex=Number(button.dataset.index);showFeedback();return true;}if(action==='feedback-prev'||action==='feedback-next'){lightboxIndex=(lightboxIndex+(action==='feedback-prev'?-1:1)+data.feedback.length)%data.feedback.length;showFeedback();return true;}
  if(action==='shop-category'){shopCategory=button.dataset.category;go('/xiaodian');return true;}
  if(action==='my-ip'){const result=await api('/api/network');$('#network-form [name="ip"]').value=result.ip;toast('已填入当前请求的网络出口 IP。');return true;}
  if(action==='download-receipt'){const current=ctx.getActiveOrder(),language=$('#receipt-language').value,res=await fetch('/api/orders/'+current.order.id+'/receipt?lang='+language,{headers:{'X-Order-Token':current.token},credentials:'same-origin'});if(!res.ok)throw new Error((await res.json()).error);const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.download='receipt-'+current.order.id+'-'+language+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('收款凭证已生成。');return true;}
  if(action==='admin-tab'){adminTab=button.dataset.tab;go('/admin');return true;}
  if(action==='content-toggle'){await api('/api/admin/content/'+encodeURIComponent(button.dataset.id),{method:'PATCH',body:{enabled:button.dataset.enabled==='yes'}});await ctx.refresh();toast('发布状态已更新。');return true;}
  if(action==='manage-activation'){const result=await api('/api/admin/orders'),o=result.orders.find(o=>o.id===button.dataset.id);showDialog(`<form id="activation-admin-form" data-id="${o.id}" data-version="${o.version}"><h2>处理激活申请</h2><p>${esc(o.id)} · ${esc(o.activation_email)}</p><label>处理结果<select name="status">${(o.activation_status==='requested'?['processing','completed','rejected']:['completed','rejected']).map(s=>`<option value="${s}">${esc(activationLabels[s])}</option>`).join('')}</select></label><label>内部备注<textarea name="note" maxlength="500">${esc(o.activation_note)}</textarea></label><p class="notice">只有实际办理并核对后才标记完成；此操作不会调用上游自动充值。</p><button class="btn full">保存激活处理结果</button></form>`);return true;}
  if(action==='manage-request'){const r=requests.find(r=>r.id===button.dataset.id);showDialog(`<form id="support-admin-form" data-id="${r.id}"><h2>处理咨询申请</h2><p>${esc(r.contact)}</p>${paragraph(r.message)}<label>状态<select name="status">${[['new','待处理'],['working','处理中'],['resolved','已处理']].map(([s,t])=>`<option value="${s}" ${s===r.status?'selected':''}>${t}</option>`).join('')}</select></label><label>内部备注<textarea name="note" maxlength="500">${esc(r.admin_note)}</textarea></label><button class="btn full">保存处理状态</button></form>`);return true;}
  if(action==='reissue-token'){showDialog(`<form id="reissue-form" data-id="${esc(button.dataset.id)}"><h2>重发订单查询凭证</h2><p>${esc(button.dataset.id)}</p><p>新凭证生成后旧凭证失效。请先核对原购买者和实际付款记录，再通过原联系渠道交给客户。</p><label class="check"><input name="verified" type="checkbox" required><span>已核实原购买者与付款记录</span></label><button class="btn full">核实并重发</button></form>`);return true;}
  return false;
 }
 function parseSections(text){const lines=String(text).split(/\r?\n/),sections=[];let current={heading:'内容说明',text:''};for(const line of lines){if(/^##\s+/.test(line)){if(current.text.trim())sections.push({...current,text:current.text.trim()});current={heading:line.replace(/^##\s+/,''),text:''};}else current.text+=line+'\n';}if(current.text.trim())sections.push({...current,text:current.text.trim()});return sections;}
 async function onSubmit(form,fd){const id=form.getAttribute('id');
  if(id==='contact-query-form'){const token=String(fd.get('token')).trim(),o=await api('/api/orders/lookup',{method:'POST',headers:{'X-Order-Token':token},body:{contact:fd.get('contact')}});ctx.remember(o.id,token);$('#order-result').innerHTML=ctx.receipt(o,token);$('#order-result').scrollIntoView({behavior:'smooth'});return true;}
  if(form.classList.contains('support-form')){const r=await api('/api/support',{method:'POST',body:{kind:form.dataset.kind,contact:fd.get('contact'),orderId:fd.get('orderId')||'',message:fd.get('message')}});form.reset();toast('申请已保存，编号 '+r.id+'。请通过客服确认后续处理。');return true;}
  if(id==='activation-form'){const orderId=String(fd.get('orderId')).trim().toUpperCase(),token=String(fd.get('token')).trim(),r=await api('/api/orders/'+encodeURIComponent(orderId)+'/activate',{method:'POST',headers:{'X-Order-Token':token},body:{code:fd.get('code'),accountEmail:fd.get('accountEmail'),agreed:fd.get('agreed')==='on'}});ctx.remember(orderId,token);$('#activation-result').innerHTML='<div class="notice">申请状态：'+esc(activationLabels[r.status])+'。可在订单页继续跟进。</div>';toast('激活申请已处理。');return true;}
  if(id==='blog-search-form'){go('/blog?q='+encodeURIComponent(String(fd.get('q')).trim()));return true;}
  if(id==='network-form'){const r=await api('/api/network/lookup',{method:'POST',body:{ip:fd.get('ip'),consent:fd.get('consent')==='on'}});$('#network-result').innerHTML=`<section class="panel"><h2>网络信息</h2><dl class="network-grid">${[['IP',r.ip],['类型',r.type],['国家 / 地区',r.country],['地区 / 城市',(r.region||'')+' '+(r.city||'')],['运营商',r.isp],['ASN',r.asn],['时区',r.timezone]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'未提供')}</dd></div>`).join('')}</dl><p class="muted">来源：${esc(r.provider)}。${esc(r.notice)}</p></section>`;return true;}
  if(form.classList.contains('product-form')){const raw=String(fd.get('price')).trim(),original=String(fd.get('originalPrice')).trim();await api('/api/admin/products/'+form.dataset.id,{method:'PATCH',body:{name:fd.get('name'),subtitle:fd.get('subtitle'),category:fd.get('category'),billingLabel:fd.get('billingLabel'),features:String(fd.get('features')).split(/\r?\n/).map(s=>s.trim()).filter(Boolean),priceCents:raw?Math.round(Number(raw)*100):null,originalPriceCents:original?Math.round(Number(original)*100):null,enabled:fd.get('enabled')==='on',deliveryMode:fd.get('deliveryMode'),deliveryInstructions:fd.get('deliveryInstructions'),activationMode:fd.get('activationMode')}});await ctx.refresh();toast('商品已保存。');return true;}
  if(id==='new-product-form'){await api('/api/admin/products',{method:'POST',body:{id:fd.get('id'),name:fd.get('name'),category:fd.get('category'),subtitle:'',billingLabel:'月',priceCents:null,enabled:false,features:[],deliveryMode:'manual',deliveryInstructions:'',activationMode:'external'}});await ctx.refresh();toast('未开售商品已创建，请继续设置价格与交付说明。');return true;}
  if(id==='post-editor-form'){const value={id:fd.get('slug'),title:fd.get('title'),category:fd.get('category'),excerpt:fd.get('excerpt'),tags:String(fd.get('tags')).split(/[,，]/).map(t=>t.trim()).filter(Boolean),sections:parseSections(fd.get('bodyText')),date:fd.get('date'),readMinutes:Number(fd.get('readMinutes')),author:site().brand};await api('/api/admin/content',{method:'POST',body:{kind:'blog',value,enabled:fd.get('enabled')==='on'}});await ctx.refresh();toast('文章已保存。');return true;}
  if(id==='feedback-editor-form'){await api('/api/admin/content',{method:'POST',body:{id:fd.get('id')||undefined,kind:'feedback',enabled:fd.get('enabled')==='on',value:{title:fd.get('title'),category:fd.get('category'),image:fd.get('image'),caption:fd.get('caption'),date:fd.get('date')}}});await ctx.refresh();toast('反馈素材已保存。');return true;}
  if(id==='support-admin-form'){await api('/api/admin/requests/'+form.dataset.id,{method:'PATCH',body:{status:fd.get('status'),note:fd.get('note')}});$('#dialog').close();await ctx.refresh();toast('申请处理状态已更新。');return true;}
  if(id==='activation-admin-form'){await api('/api/admin/orders/'+form.dataset.id+'/activate',{method:'PATCH',body:{status:fd.get('status'),note:fd.get('note'),version:Number(form.dataset.version)}});$('#dialog').close();await ctx.refresh();toast('激活状态已更新。');return true;}
  if(id==='reissue-form'){const r=await api('/api/admin/orders/'+form.dataset.id+'/reissue',{method:'POST',body:{verified:fd.get('verified')==='on'}});showDialog(`<h2>新查询凭证已生成</h2><p>${esc(r.id)}</p><code class="token">${esc(r.token)}</code><p>请通过已核实的原联系渠道交给客户。关闭后不会再次显示明文凭证，旧凭证已失效。</p>`);return true;}
  return false;
 }
 function onInput(event){const target=event.target;if(target.id==='extended-question-search')filterQuestions();if(target.id==='admin-order-search'){const q=target.value.trim().toLowerCase();document.querySelectorAll('#admin-order-rows tr[data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(q));}if(target.id==='edit-post-select'){const item=adminItems.find(i=>i.id===target.value),form=$('#post-editor-form');if(!item){form.reset();return;}const p=item.value;for(const [key,value] of Object.entries({slug:p.id,title:p.title,category:p.category,excerpt:p.excerpt,tags:p.tags.join(', '),bodyText:p.sections.map(s=>'## '+s.heading+'\n'+s.text).join('\n\n'),date:p.date,readMinutes:p.readMinutes||4})){form.elements.namedItem(key).value=value;}form.elements.namedItem('enabled').checked=!!item.enabled;}}

 const referenceContext={api,esc,money,date,go,toast,showDialog,site,card,link,heading,faqRows,videoPanel,saved:ctx.saved,remember:ctx.remember};
 const referencePages=createReferencePages(referenceContext),portalPages=createPortalPages(referenceContext);
 return {nav,footer,orderExtras,load:async()=>{data=await api('/api/content');},route:async path=>{
  const independent=referencePages.route(path)||portalPages.route(path);if(independent)return independent;
  if(path==='/')return home();if(path==='/plus-price')return pricePage();if(['/gptpro','/chatgpt-pro'].includes(path))return proPage();if(path==='/chatgpt-plus')return plusTopic();
  if(path==='/purchase')return purchase('plus');if(path==='/purchase-team')return purchase('business');if(path==='/purchase-go')return purchase('go');if(path==='/purchase-gptplus')return purchase('plusaccount');if(path==='/purchase-gptpro')return purchase(new URLSearchParams(location.search).get('tier')==='gptpro'?'pro200':'pro100');if(path==='/purchase-upgrade-pro')return purchase(new URLSearchParams(location.search).get('tier')==='gptpro'?'pro200':'pro100');
  if(path==='/purchase_credits')return credits();if(path==='/checkout')return purchase(new URLSearchParams(location.search).get('plan'));if(path==='/order')return orderPage();if(path==='/gptget')return activation();if(path==='/guide')return guide();if(path==='/faq')return questions(false);if(path==='/help')return questions(true);
  if(path==='/blog')return blog();if(path.startsWith('/blog/tag/'))return blog(path.slice('/blog/tag/'.length));if(path.startsWith('/blog/'))return article(path.slice(6));if(path==='/codex-phone-verification')return article('codex-phone-verification');
  if(path==='/feedback')return feedback();if(['/codex','/credits'].includes(path))return codex();if(['/gemini-pro','/grok','/claude'].includes(path))return aiService(path==='/gemini-pro'?'gemini':path.slice(1));if(path==='/xiaodian')return shop();if(['/team','/business-recharge'].includes(path))return team();if(path==='/ip')return network();if(['/about','/privacy','/terms'].includes(path))return information(path.slice(1));if(path==='/admin')return adminPage();return null;
 },click:async button=>await referencePages.click(button)||await portalPages.click(button)||onClick(button),submit:async(form,fd)=>await referencePages.submit(form,fd)||await portalPages.submit(form,fd)||onSubmit(form,fd),input:event=>onInput(event)};
}
